+
+      .choice {
+        display: flex;
+        align-items: center;
+        gap: 12px;
+        padding: 14px 16px;
+        border-radius: 14px;
+        border: 1px solid rgba(148, 163, 184, 0.14);
+        background: rgba(15, 23, 42, 0.9);
+        transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
+        cursor: pointer;
