+          helpText: "Select every option that is widely used to write software.",
+          options: ["Python", "JavaScript", "HTML", "Ruby"],
+        },
+        {
+          id: "question-2",
+          title: "Which languages are strongly associated with systems programming?",
+          options: ["Rust", "C", "Swift", "COBOL"],
+        },
+        {
+          id: "question-3",
+          title: "Which of these are query or markup languages rather than general-purpose programming languages?",
+          options: ["SQL", "XML", "TypeScript", "Go"],
+        },
+      ];
+
