        margin-bottom: 20px;
        padding: 22px;
        border-radius: 18px;
        border: 1px solid rgba(148, 163, 184, 0.12);
        background: rgba(15, 23, 42, 0.84);
      }

      .question-label {
        display: block;
        margin-bottom: 6px;
        font-size: 1.1rem;
        font-weight: 700;
      }

      .help-text {
        margin: 0 0 16px;
        color: var(--muted);
        font-size: 0.95rem;
