          id: "question-1",
          title: "Which of these are commonly used programming languages?",
          helpText: "Select every option that is widely used to write software.",
          options: ["Python", "JavaScript", "HTML", "Ruby"],
        },
        {
          id: "question-2",
          title: "Which languages are strongly associated with systems programming?",
          options: ["Rust", "C", "Swift", "COBOL"],
        },
        {
          id: "question-3",
          title: "Which of these are query or markup languages rather than general-purpose programming languages?",
          options: ["SQL", "XML", "TypeScript", "Go"],
        },
      ];

      const createChoice = (questionId, option, optionIndex) => `
        <label class="choice">
          <input type="checkbox" name="${questionId}" value="${option}" id="${questionId}-${optionIndex}" />
          <span>${option}</span>
        </label>
      `;

      const QuizQuestion = ({ id, title, helpText, options }) => `
        <div class="form-field">
          <span class="question-label">${title}</span>
          ${helpText ? `<p class="help-text">${helpText}</p>` : ""}
          <div class="choices">
            ${options.map((option, index) => createChoice(id, option, index)).join("")}
          </div>
        </div>
      `;

      const App = () => `
        <main class="page-shell">
          <section class="quiz-card">
            <p class="eyebrow">Interactive Quiz</p>
            <h1>Computer Languages Challenge</h1>
            <p class="intro">
