        ).length;

        const result = document.getElementById("result");
        result.textContent =
          answered === quizQuestions.length
            ? "Quiz submitted. You answered every question."
            : `Quiz submitted. You answered ${answered} of ${quizQuestions.length} questions.`;
      });
    </script>
  </body>
</html>
