                 <div id="result" class="result" aria-live="polite"></div>
               </div>
             </form>
           </section>
         </main>
       `;

       document.getElementById("app").innerHTML = App();

       document.getElementById("quiz-form").addEventListener("submit", (event) => {
         event.preventDefault();
         const answered = quizQuestions.filter((question) =>
           document.querySelector(`input[name="${question.id}"]:checked`)
         ).length;

         const result = document.getElementById("result");
         result.textContent =
           answered === quizQuestions.length
             ? "Quiz submitted. You answered every question."
             : `Quiz submitted. You answered ${answered} of ${quizQuestions.length} questions.`;
       });
